conversion:
// js
const days = get(ctx, 'work.days', []);
if (days.length === 0) return 0;
const terms = get(ctx.subject.employment, 'terms', {});
const rate = get(terms, 'rate', {});
const unit = get(rate, 'unit', 'MONTHLY');
const agreed = Number(get(rate, 'amount', 0));
const sixDay = Number(get(terms, 'normal_days_per_week', 0)) === ctx.lookup.six_day_week;
const monthly =
	unit === 'PIECE' || agreed <= 0
		? ctx.base_pay
		: unit === 'DAILY'
			? agreed * (sixDay ? ctx.lookup.daily_paid_days_six_day : ctx.lookup.daily_paid_days_five_day)
			: unit === 'HOURLY'
				? (agreed * Number(get(terms, 'normal_hours_per_week', 0)) * 52) / 12
				: agreed;
const allowances = Object.entries(get(terms, 'allowances', {}));
const fixed = sum(
	allowances
		.filter(([, allowance]) => get(allowance, 'variability', 'FIXED') === 'FIXED')
		.map(([, allowance]) => Number(get(allowance, 'amount', 0)))
);
const variable = sum(
	allowances
		.filter(([, allowance]) => get(allowance, 'variability', 'FIXED') === 'VARIABLE')
		.map(([, allowance]) => Number(get(allowance, 'amount', 0)))
);
const baseWage = Math.max(
	monthly + fixed,
	ctx.lookup.wage_floor_factor * (monthly + fixed + variable)
);
const hourly = baseWage / ctx.lookup.divisor;
const ordinary = (day) =>
	['WORK', ''].includes(String(get(day, 'day_type', ''))) && !get(day, 'holiday_kind', '');
const bandsOf = (day) => {
	if (ordinary(day)) return ctx.lookup.ordinary_bands;
	if (!sixDay) return ctx.lookup.five_day_bands;
	return String(get(day, 'day_type', '')) === 'WORK' &&
		Number(get(day, 'scheduled_hours', 0)) <= ctx.lookup.short_day_hours
		? ctx.lookup.six_day_short_bands
		: ctx.lookup.six_day_bands;
};
const price = (day) => {
	const hours = ordinary(day)
		? Number(get(day, 'overtime_hours', 0))
		: Number(get(day, 'worked_hours', 0)) - Number(get(day, 'banked_hours', 0));
	if (hours <= 0) return 0;
	return ladder(hours, bandsOf(day)) * hourly;
};
return sum(days.map(price));
